bench.cmd:
V=physical/hbm_accel_die_views; O={RUN}/neg; mkdir -p $O
sed 's/b\[bbeat\] <= bdata/b[bbeat ^ 5'"'"'d1] <= bdata/' $V/svc/rtl/ot_hbm_svc_core.sv > $O/core_mutant.sv
cmp -s $O/core_mutant.sv $V/svc/rtl/ot_hbm_svc_core.sv && { echo 'mutant not applied'; exit 0; }
sed 's/hfd_svc_SW dut/hfd_svc_SW_seg dut/' $V/svc/tb/tb_hfd_svc_SW.sv > $O/tb.sv
iverilog -g2012 -o $O/neg.vvp -I $V/svc/tb -s tb_hfd_svc_SW rtl/hbm_accel/service/ot_hbm_accel_cdc_fifo.sv $O/core_mutant.sv $V/svc/rtl/ot_hbm_svc_seg_lib.sv $V/svc/rtl/seg/hfd_svc_SW_s[0-9].sv $V/svc/rtl/seg/hfd_svc_SW_seg.sv $V/svc/tb/tb_svc_physide.sv $O/tb.sv || { echo BUILD_FAILED; exit 0; }
vvp -n $O/neg.vvp > $O/neg.log 2>&1; rc=$?; grep SVC_BENCH $O/neg.log | tail -2; exit $rc
